{
  "name": "pyUVVIS紫外-可见光谱采集软件",
  "name_en": "pyUVVIS UV-Vis Acquisition Application",
  "manufacturer": "",
  "description": "一个非物理的桌面图形软件组件，用于实验中的紫外-可见光谱采集与显示。它可连接 UC480 相机或 Ocean Optics 光谱输入设备，执行实时读数、波长轴处理、曝光与增益调节、暗背景扣除、平均记录、曲线绘图，以及数据保存和加载。",
  "description_en": "A non-physical desktop GUI software component for UV-Vis spectral acquisition and display in laboratory experiments. It can connect to UC480 cameras or Ocean Optics spectral input devices, perform real-time readout, wavelength-axis handling, exposure and gain adjustment, dark subtraction, averaging/recording, curve plotting, and data save/load operations.",
  "actions": [
    {
      "action_name": "auto-createUI",
      "description": "创建图形用户界面。",
      "description_en": "Create the graphical user interface."
    },
    {
      "action_name": "auto-createTB",
      "description": "创建工具栏并绑定界面事件。",
      "description_en": "Create the toolbar and bind UI events."
    },
    {
      "action_name": "auto-createPlotWnd",
      "description": "创建光谱绘图窗口。",
      "description_en": "Create the spectrum plotting window."
    },
    {
      "action_name": "auto-connectCamera",
      "description": "连接当前选择的相机输入设备。",
      "description_en": "Connect the currently selected camera input device."
    },
    {
      "action_name": "auto-connectUC480",
      "description": "连接 UC480 相机。",
      "description_en": "Connect a UC480 camera."
    },
    {
      "action_name": "auto-connectOO",
      "description": "连接 Ocean Optics 光谱输入设备。",
      "description_en": "Connect an Ocean Optics spectral input device."
    },
    {
      "action_name": "auto-camClose",
      "description": "关闭当前相机或输入设备连接。",
      "description_en": "Close the current camera or input-device connection."
    },
    {
      "action_name": "auto-readCamera",
      "description": "从活动输入设备读取一帧数据。",
      "description_en": "Read one frame from the active input device."
    },
    {
      "action_name": "auto-camSupportsGain",
      "description": "检查当前设备是否支持增益调节。",
      "description_en": "Check whether the current device supports gain adjustment."
    },
    {
      "action_name": "auto-camSupportsExp",
      "description": "检查当前设备是否支持曝光调节。",
      "description_en": "Check whether the current device supports exposure adjustment."
    },
    {
      "action_name": "auto-camSetGain",
      "description": "设置当前设备的增益。",
      "description_en": "Set the gain of the current device."
    },
    {
      "action_name": "auto-camSetExp",
      "description": "设置当前设备的曝光时间。",
      "description_en": "Set the exposure time of the current device."
    },
    {
      "action_name": "auto-getWlAxis",
      "description": "获取波长轴数据。",
      "description_en": "Get the wavelength axis data."
    },
    {
      "action_name": "auto-addLine",
      "description": "向绘图窗口添加一条曲线。",
      "description_en": "Add a curve to the plot window."
    },
    {
      "action_name": "auto-refreshPlot",
      "description": "刷新绘图窗口显示。",
      "description_en": "Refresh the plot window display."
    },
    {
      "action_name": "auto-OnQuit",
      "description": "退出程序并关闭相关模块。",
      "description_en": "Quit the application and close related modules."
    },
    {
      "action_name": "auto-OnTBSave",
      "description": "保存当前光谱数据。",
      "description_en": "Save the current spectrum data."
    },
    {
      "action_name": "auto-OnTBLoad",
      "description": "加载已保存的光谱数据。",
      "description_en": "Load saved spectrum data."
    },
    {
      "action_name": "auto-OnTBDelete",
      "description": "删除最近添加的曲线。",
      "description_en": "Delete the most recently added curve."
    },
    {
      "action_name": "auto-OnTBAvgInc",
      "description": "增加平均次数设置。",
      "description_en": "Increase the averaging setting."
    },
    {
      "action_name": "auto-OnTBAvgDec",
      "description": "减少平均次数设置。",
      "description_en": "Decrease the averaging setting."
    },
    {
      "action_name": "auto-OnTBGainInc",
      "description": "增加增益设置。",
      "description_en": "Increase the gain setting."
    },
    {
      "action_name": "auto-OnTBGainDec",
      "description": "减少增益设置。",
      "description_en": "Decrease the gain setting."
    },
    {
      "action_name": "auto-OnTBExpInc",
      "description": "增加曝光设置。",
      "description_en": "Increase the exposure setting."
    },
    {
      "action_name": "auto-OnTBExpDec",
      "description": "减少曝光设置。",
      "description_en": "Decrease the exposure setting."
    },
    {
      "action_name": "auto-OnRTBAvgInc",
      "description": "在实时工具栏中增加平均次数设置。",
      "description_en": "Increase the averaging setting from the realtime toolbar."
    },
    {
      "action_name": "auto-OnRTBAvgDec",
      "description": "在实时工具栏中减少平均次数设置。",
      "description_en": "Decrease the averaging setting from the realtime toolbar."
    },
    {
      "action_name": "auto-OnRTBGainInc",
      "description": "在实时工具栏中增加增益设置。",
      "description_en": "Increase the gain setting from the realtime toolbar."
    },
    {
      "action_name": "auto-OnRTBGainDec",
      "description": "在实时工具栏中减少增益设置。",
      "description_en": "Decrease the gain setting from the realtime toolbar."
    },
    {
      "action_name": "auto-OnRTBExpInc",
      "description": "在实时工具栏中增加曝光设置。",
      "description_en": "Increase the exposure setting from the realtime toolbar."
    },
    {
      "action_name": "auto-OnRTBExpDec",
      "description": "在实时工具栏中减少曝光设置。",
      "description_en": "Decrease the exposure setting from the realtime toolbar."
    },
    {
      "action_name": "auto-OnTBStart",
      "description": "开始采集或测量。",
      "description_en": "Start acquisition or measurement."
    },
    {
      "action_name": "auto-OnTBRecord",
      "description": "切换记录或平均采集状态。",
      "description_en": "Toggle recording or averaged acquisition."
    },
    {
      "action_name": "auto-OnTBMode",
      "description": "切换显示或测量模式。",
      "description_en": "Switch the display or measurement mode."
    },
    {
      "action_name": "auto-OnTBAuto",
      "description": "自动调整曝光和增益。",
      "description_en": "Automatically adjust exposure and gain."
    },
    {
      "action_name": "auto-OnTBDark",
      "description": "执行暗背景采集或暗信号校正。",
      "description_en": "Perform dark-background acquisition or dark-signal correction."
    },
    {
      "action_name": "auto-OnUpdate",
      "description": "执行主测量更新循环，读取数据并更新显示。",
      "description_en": "Run the main measurement update loop, read data, and update the display."
    }
  ],
  "tag_hints": [
    "UV-Vis spectroscopy",
    "spectral acquisition GUI",
    "real-time plotting",
    "Ocean Optics spectrometer",
    "UC480 camera",
    "dark subtraction",
    "exposure and gain control",
    "wavelength calibration"
  ]
}

